t='\n'.join(re.sub(r'^\d+\|','',x) for x in r.get('content','').splitlines())
try:
 d=json.loads(t); print('count',d.get('count'))
 for x in d.get('results',[]): print(x.get('when'),x.get('session_id'),x.get('snippet','')[:500].replace('\n',' '))
except Exception as e: print('error',e,'total',r.get('total_lines'), t[:500])

